INSERT INTO feature VALUES('derivation-index','editor','The tree of each declaration''s judgement nodes','instrument-seam','implemented','notable',NULL,'At the trace layer, each run of the checker''s machine writes one fixed-size record for each step into a buffer that the incremental pass lends the checking context: a goal started, a goal the memo answered, a result handed and a refusal. A record names its node and its type by arena id, and no record allocates. At the end of each judged item the session folds the item''s steps into the tree of its judgement nodes in pre-order, each node with its direction, goal, type, memo mark, cover, nodes visited and wall. The account keeps each tree by the declaration''s content key beside its revision''s program and the names its source writes for its binders, so a face prints a goal, its type and its rule on demand: each binder as written, and each variable bound above a node by its binder''s name. The tree also keeps the copies and the binds of the body''s elaboration, so the goals of the second run over the elaborated body print under that renaming: a copied binder as its source names it, and a variable of a minted bind as the term the bind binds. An adopted declaration keeps its tree, and a node reads replayed once the kernel replays its declaration.','core-checker core-incremental surface-session surface-diagnostics surface-pretty surface-lsp','crates/surface-session/tests/trace.rs crates/core-checker-base/src/judgement/memo/tests.rs crates/surface-lsp/src/server.rs','crate-tests','#6294');
